begin; select set_config('request.jwt.claim.sub','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d',true); select set_config('request.jwt.claims','{"sub":"7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d","role":"authenticated"}',true); do $$ begin if not exists(select 1 from schoolpro_schools where id='d342eb87-8d6a-477a-a380-7fab83f586b7' and owner_id='7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' and name='IHLINK ACADEMY (Testing)')then raise exception 'Testing Academy only';end if;end $$;

insert into schoolpro_question_bank(id,school_id,subject_id,class_id,question_type,question_text,options,correct_answer,marks,explanation,created_by)
select md5('ihlink-academy-test-v1:question:'||c.id||':'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',sa.subject_id,c.id,'objective','TEST: Number practice '||n||': what is '||n||' + '||n||'?',jsonb_build_array((2*n)::text,(2*n+1)::text,(2*n-1)::text,(2*n+2)::text),(2*n)::text,2,'Add equal groups or use repeated addition.',m.user_id from schoolpro_classes c join schoolpro_subject_assignments sa on sa.class_id=c.id and sa.session='2025/2026' join schoolpro_subjects sub on sub.id=sa.subject_id join schoolpro_members m on m.id=sa.teacher_member_id cross join generate_series(1,10)n where c.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and sub.code like 'TST-%-02' on conflict(id)do nothing;
insert into schoolpro_cbt_tests(id,school_id,title,subject_id,class_id,duration_minutes,total_marks,status,created_by,instructions,opens_at,closes_at,test_type)
select md5('ihlink-academy-test-v1:cbt:'||c.id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','TEST: Mathematics practice — '||c.name||' '||c.arm,sa.subject_id,c.id,20,20,'published',m.user_id,'Testing practice only. Answer all ten questions.',now()-interval '1 day',now()+interval '30 days','internal' from schoolpro_classes c join schoolpro_subject_assignments sa on sa.class_id=c.id and sa.session='2025/2026' join schoolpro_subjects sub on sub.id=sa.subject_id join schoolpro_members m on m.id=sa.teacher_member_id where c.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and sub.code like 'TST-%-02' on conflict(id)do nothing;
insert into schoolpro_cbt_test_questions(id,test_id,question_id,position)
select md5('ihlink-academy-test-v1:test-question:'||q.id)::uuid,t.id,q.id,row_number()over(partition by t.id order by q.question_text) from schoolpro_cbt_tests t join schoolpro_question_bank q on q.class_id=t.class_id and q.school_id=t.school_id where t.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and t.title like 'TEST:%' and q.question_text like 'TEST:%' on conflict(id)do nothing;
insert into schoolpro_cbt_eligibility(id,school_id,test_id,class_id,eligible,assigned_by)
select md5('ihlink-academy-test-v1:cbt-eligibility:'||id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',id,class_id,true,'7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' from schoolpro_cbt_tests where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and title like 'TEST:%' on conflict(id)do nothing;
insert into schoolpro_cbt_attempts(id,test_id,student_id,started_at,submitted_at,score,status,attempt_no)
select md5('ihlink-academy-test-v1:cbt-attempt:'||s.id)::uuid,t.id,s.id,now()-interval '2 hours',now()-interval '110 minutes',2*(5+right(s.admission_number,3)::int%6),'submitted',1 from schoolpro_students s join schoolpro_cbt_tests t on t.class_id=s.class_id where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and right(s.admission_number,3)::int<=10 and t.title like 'TEST:%' on conflict(id)do nothing;
insert into schoolpro_cbt_answers(id,attempt_id,question_id,answer,is_correct,marks_awarded,feedback)
select md5('ihlink-academy-test-v1:cbt-answer:'||a.id||':'||q.id)::uuid,a.id,q.id,case when tq.position<=a.score/2 then q.correct_answer else (q.correct_answer::int+1)::text end,tq.position<=a.score/2,case when tq.position<=a.score/2 then 2 else 0 end,'TEST: automatically marked practice answer' from schoolpro_cbt_attempts a join schoolpro_cbt_test_questions tq on tq.test_id=a.test_id join schoolpro_question_bank q on q.id=tq.question_id where a.id in(select md5('ihlink-academy-test-v1:cbt-attempt:'||s.id)::uuid from schoolpro_students s where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%') on conflict(id)do nothing;
insert into schoolpro_admissions(id,school_id,applicant_name,first_name,last_name,guardian_name,guardian_email,class_applied,status,notes,application_number,submitted_at,entrance_score)
select md5('ihlink-academy-test-v1:admission:'||n)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','Test Applicant '||n,'Test Applicant',n::text,'Test Guardian '||n,'ihacademy.applicant.'||n||'@example.com',(array['Nursery 1 A','Basic 1 A','JSS 1 A','SS 1 A'])[1+(n-1)%4],case when n<=4 then 'pending' when n<=8 then 'reviewing' when n<=12 then 'rejected' else 'pending' end,'TEST: fabricated application for admissions workflow','IH-TST-APP-'||lpad(n::text,3,'0'),now(),case when n>4 then 45+n else null end from generate_series(1,16)n on conflict(id)do nothing;
insert into schoolpro_admission_events(id,application_id,event_type,scheduled_at,location,notes,status)
select md5('ihlink-academy-test-v1:screening:'||n)::uuid,md5('ihlink-academy-test-v1:admission:'||n)::uuid,'interview',now()+interval '7 days','Academy test office','TEST: guardian and applicant screening example','scheduled' from generate_series(5,8)n on conflict(id)do nothing;
insert into schoolpro_promotions(id,school_id,student_id,from_class,from_class_id,to_class,to_class_id,session,status,decision,decided_by,reason)
select md5('ihlink-academy-test-v1:progression:'||s.id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',s.id,s.class_name,s.class_id,s.class_name,s.class_id,'2025/2026','pending','repeated','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d','TEST: progression review; pending decision does not move the pupil.' from schoolpro_students s where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and right(s.admission_number,3)::int in(35,36) on conflict(id)do nothing;
insert into schoolpro_promotions(id,school_id,student_id,from_class,from_class_id,session,status,decision,decided_by,reason)
select md5('ihlink-academy-test-v1:graduation:'||s.id)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',s.id,s.class_name,s.class_id,'2025/2026','pending','graduated','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d','TEST: completed senior secondary programme.' from schoolpro_students s join schoolpro_classes c on c.id=s.class_id where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and c.name='SS 3' and right(s.admission_number,3)::int in(39,40) on conflict(id)do nothing;
do $$ declare r record;begin for r in select id from schoolpro_promotions where school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and reason='TEST: completed senior secondary programme.' and status='pending' loop perform apply_schoolpro_promotion(r.id);end loop;end $$;
insert into schoolpro_academic_documents(id,school_id,student_id,document_type,title,session,issued_by,issued_at,metadata)
select md5('ihlink-academy-test-v1:academic-document:'||s.id||':'||kind)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',s.id,kind,'TEST: '||case when kind='certificate' then 'Senior secondary completion certificate' when kind='transcript' then 'Three-term transcript' else 'Student identity card' end,'2025/2026','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d',now(),jsonb_build_object('synthetic',true,'fixture','ihlink-academy-v1','student_name',s.first_name||' '||s.last_name,'class_name',s.class_name,'admission_number',s.admission_number,'school_name','IHLINK ACADEMY (Testing)','purpose','Testing document preview') from schoolpro_students s cross join unnest(array['id_card','certificate','transcript'])kind where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and s.admission_number like 'IH-TST-2026-%' and (right(s.admission_number,3)::int=1 or s.status='graduated') on conflict(id)do nothing;
insert into schoolpro_document_issues(id,school_id,template_id,student_id,document_type,title,payload,status,issued_by)
select md5('ihlink-academy-test-v1:document-issue:'||s.id||':'||t.document_type)::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7',t.id,s.id,t.document_type,'TEST: '||t.name,jsonb_build_object('synthetic',true,'student_name',s.first_name||' '||s.last_name,'first_name',s.first_name,'last_name',s.last_name,'admission_number',s.admission_number,'class_name',s.class_name,'school_name','IHLINK ACADEMY (Testing)','session','2025/2026','term','Third Term','issue_date',current_date::text,'design_snapshot',jsonb_build_object('settings',t.settings,'field_mappings',t.field_mappings,'storage_path',t.storage_path,'source_format',t.source_format,'mime_type',t.mime_type)),'draft','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d' from schoolpro_students s cross join schoolpro_document_templates t where s.school_id='d342eb87-8d6a-477a-a380-7fab83f586b7' and t.school_id=s.school_id and s.admission_number like 'IH-TST-2026-%' and (right(s.admission_number,3)::int=1 or s.status='graduated') on conflict(id)do nothing;
insert into schoolpro_notifications(id,school_id,user_id,title,message,kind,href)
values(md5('ihlink-academy-test-v1:discipline-summary')::uuid,'d342eb87-8d6a-477a-a380-7fab83f586b7','7a65cdab-a9c3-412d-b5d8-7d1bcd857c1d','TEST: Classroom concerns awaiting review','Sample teacher complaints are available in Discipline. Review and decide whether guardian contact is needed.','info','/schoolpro/discipline') on conflict(id)do nothing;
